const updateOIDCClient = `-- name: UpdateOIDCClient :one
UPDATE auth.oidc_clients SET
    name             = COALESCE($1, name),
    redirect_uris    = COALESCE($2, redirect_uris),
    post_logout_uris = COALESCE($3, post_logout_uris),
    grant_types      = COALESCE($4, grant_types),
    scopes           = COALESCE($5, scopes),
    pkce_exempt_until = CASE WHEN $6::bool
                             THEN $7::timestamptz
                             ELSE pkce_exempt_until END
WHERE id = $8 AND tenant_id = $9
RETURNING id, tenant_id, client_id, type, name, redirect_uris,
          post_logout_uris, grant_types, scopes, created_at, pkce_exempt_until
`

type UpdateOIDCClientParams struct {
	Name               *string
	RedirectUris       []string
	PostLogoutUris     []string
	GrantTypes         []string
	Scopes             []string
	SetPkceExemptUntil bool
	PkceExemptUntil    pgtype.Timestamptz
	ID                 uuid.UUID
	TenantID           uuid.UUID
}

type UpdateOIDCClientRow struct {
	ID              uuid.UUID
	TenantID        uuid.UUID
	ClientID        string
	Type            string
	Name            string
	RedirectUris    []string
	PostLogoutUris  []string
	GrantTypes      []string
	Scopes          []string
	CreatedAt       time.Time
	PkceExemptUntil pgtype.Timestamptz
}

func (q *Queries) UpdateOIDCClient(ctx context.Context, arg UpdateOIDCClientParams) (UpdateOIDCClientRow, error) {
	row := q.db.QueryRow(ctx, updateOIDCClient,
		arg.Name,
		arg.RedirectUris,
		arg.PostLogoutUris,
		arg.GrantTypes,
		arg.Scopes,
		arg.SetPkceExemptUntil,
		arg.PkceExemptUntil,
		arg.ID,
		arg.TenantID,
	)
	var i UpdateOIDCClientRow
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.ClientID,
		&i.Type,
		&i.Name,
		&i.RedirectUris,
		&i.PostLogoutUris,
		&i.GrantTypes,
		&i.Scopes,
		&i.CreatedAt,
		&i.PkceExemptUntil,
	)
	return i, err
}

